theorem Computation.DegreeMonoid.degPeriod_prodRel{R : α → α → Prop} {S : β → β → Prop} {a : α} {b : β}
    (ha : ∃ n ∈ degreeMonoid R a, n ≠ 0) (hb : ∃ n ∈ degreeMonoid S b, n ≠ 0) :
    degPeriod (prodRel R S) (a, b) = Nat.lcm (degPeriod R a) (degPeriod S b) := by sorry

theorem Round10.least_complete_exponent_prod(P : Finset ℕ) (hP : ∀ r ∈ P, r.Prime) :
    IsLeast {m : ℕ | 0 < m ∧ freeWitness (∏ r ∈ P, r) m = ∏ r ∈ P, (r - 1)}
      (P.lcm (fun r => r - 1)) := by sorry

theorem Round10.least_complete_exponent_odd{N : ℕ} (hodd : Odd N) (hN : N ≠ 0) :
    IsLeast {m : ℕ | 0 < m ∧ freeWitness N m = Nat.totient N}
      (N.primeFactors.lcm fun p => Nat.totient (p ^ N.factorization p)) := by sorry
